### Deterministic parallel work units

An operation may now run more than one work unit at a time:

```json
{
  "objective": "Add a --dry-run flag",
  "policy": { "maxConcurrentUnits": 2 },
  "resources": [
    { "id": "primary", "endpoint": "https://api.example/v1", "model": "m1" },
    { "id": "secondary", "endpoint": "https://api.example/v1", "model": "m2", "maxConcurrentUnits": 1 }
  ],
  "units": [
    { "id": "impl", "role": "implementer", "prompt": "…" },
    { "id": "docs", "role": "implementer", "prompt": "…" },
    { "id": "test", "role": "tester", "dependsOn": ["impl"], "prompt": "…" },
export function configuredOperationPolicy(setting: (key: string) => string | undefined = operatorSetting): HarnessConfig["operationPolicy"] {
  if (operatorJsonOperationPolicyError) throw operatorJsonOperationPolicyError;
  // Node timers clamp larger delays to 1 ms. Keep operator policy inside the
  // supported timer range so long waits cannot turn into a wake/revalidate loop.
  const maxTimerDelayMs = 2_147_483_647;
  const fields = [
    ["NEXUS_OPERATION_MAX_WAIT_MS", "maxWaitMs", 1],
    ["NEXUS_OPERATION_UNKNOWN_RESUME_BUDGET", "unknownResumeBudget", 0],
    ["NEXUS_OPERATION_MAX_RUNS_PER_UNIT", "maxRunsPerUnit", 1],
    ["NEXUS_OPERATION_MIN_WAIT_MS", "minWaitMs", 1],
  ] as const;
  const policy: NonNullable<HarnessConfig["operationPolicy"]> = {};
  for (const [key, property, minimum] of fields) {
    const shellValue = shellEnvironment[key];
    const legacyFileValue = userConfigFile[key];
    const structuredValue = operatorJsonOperationPolicy?.[property];
    // Shell overrides the structured file; config.json supersedes config.env; config.env remains a
    // compatibility fallback. `setting` remains injectable and covers callers before environment loading.
    const raw = shellValue !== undefined
      ? shellValue
      : structuredValue !== undefined
        ? String(structuredValue)
        : legacyFileValue !== undefined
          ? legacyFileValue
          : setting(key);
    if (raw === undefined) continue;
    if (!/^\d+$/.test(raw.trim())) {
      throw new Error(`Invalid ${key}='${raw}': expected a non-empty decimal integer.`);
    }
    const value = Number(raw);
    if (!Number.isSafeInteger(value) || value < minimum) {
      throw new Error(`Invalid ${key}='${raw}': expected a safe integer of at least ${minimum}.`);
    }
    if ((property === "maxWaitMs" || property === "minWaitMs") && value > maxTimerDelayMs) {
      throw new Error(`Invalid ${key}='${raw}': must not exceed Node's timer limit (${maxTimerDelayMs} ms).`);
    }
    policy[property] = value;
  }
  return Object.keys(policy).length ? policy : undefined;
}

/** The home whose `~/.config/nexus/config.json` is operator policy: the credential authority's once recorded, else the process owner's. */
export function operatorConfigHome(): string {
  return credentialAuthorityRecorded ? credentialStorageHome() : os.homedir();
}

/** The validated operator `config.json`: the operation policy, plus the `worktree` block as written (its reader validates it). */
